/**
 * `@tricc/core/lang`: tricc's shared expression languages (a pinned copy of `tricc_oo/lang/`,
 * see `lang.lock.json`) with parsers generated by ANTLR 4.13.2. A separate entry, so the main
 * one does not load ANTLR: import it lazily (feature/20261125-expression-languages.md).
 */
import lock from './lang.lock.json' with { type: 'json' }
import meaning from './meaning.json' with { type: 'json' }
import cells from './feel/cells.json' with { type: 'json' }
import { isExpressionArg } from './cql.js'
import { validateExpressions } from './validate.js'
import { checkCapabilities } from './capabilities.js'

export {
  FUNCTIONS,
  cqlErrors,
  cqlKind,
  cqlUses,
  isExpressionArg,
  literalValue,
  normaliseCql,
  parseCql,
  unquoteLiteral,
  type CatalogueFunction,
  type CqlError,
  type CqlKind,
  type CqlUse,
  type ParsedCql,
} from './cql.js'
export {
  CellError,
  cellMatches,
  cellValue,
  parseCell,
  type CellColumnType,
  type CellTest,
  type CellValue,
} from './feel.js'
export { nodeExpressions, validateExpressions } from './validate.js'
export { BUILT_OUTPUTS, checkCapabilities } from './capabilities.js'

/** The tricc-lang version of the pinned copy. */
export const LANG_VERSION: string = lock.version
/** The pinned copy's lock: version, tricc commit, sha256. */
export const LANG_LOCK = lock
/** The shared meaning rules (`meaning.json`). */
export const MEANING = meaning
/** The shared decision-table cell vector (`feel/cells.json`). */
export const CELL_VECTORS = cells

/** What `validateProject(project, { lang })` needs from this module. */
export const langValidation = { isExpressionArg, validateExpressions, checkCapabilities }
